// DeliveryOptimizerSinglePage.js

import React, { useState, useEffect } from 'react';
import MapDisplay from './MapDisplay';
import './App.css';

function DeliveryOptimizerSinglePage() {
  // State variables for your daily customer count, etc.
  const [dailyCustomerCount, setDailyCustomerCount] = useState(0);
  const [customers, setCustomers] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [numTrucks, setNumTrucks] = useState(0);
  const [productWeight, setProductWeight] = useState(0);

  const [storages, setStorages] = useState([]);
  const [selectedStorageId, setSelectedStorageId] = useState(null);
  const [selectedCustomerIds, setSelectedCustomerIds] = useState([]);

  const [optimizationResult, setOptimizationResult] = useState(null);

  // Fetch customers and storages from backend
  useEffect(() => {
    fetch("http://127.0.0.1:5000/customers")
      .then(res => res.json())
      .then(data => setCustomers(data.customers || []))
      .catch(err => console.error("Error fetching customers:", err));

    fetch("http://127.0.0.1:5000/storages")
      .then(res => res.json())
      .then(data => {
        setStorages(data.storages || []);
        if(data.storages && data.storages.length > 0) {
          setSelectedStorageId(data.storages[0].id);
        }
      })
      .catch(err => console.error("Error fetching storages:", err));
  }, []);

  // Toggle customer selection
  const handleCustomerToggle = (customerId) => {
    setSelectedCustomerIds(prev =>
      prev.includes(customerId)
        ? prev.filter(id => id !== customerId)
        : [...prev, customerId]
    );
  };

  // Filter customers based on search
  const filteredCustomers = customers.filter(c =>
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    c.address.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Submit handler
  const handleSubmit = async () => {
    const selectedCustomers = customers.filter(c => selectedCustomerIds.includes(c.id));
    const customerLocations = selectedCustomers.map(c => c.location);
    const selectedStorage = storages.find(s => s.id === selectedStorageId);

    const payload = {
      locations: customerLocations,
      num_vehicles: numTrucks,
      depot: selectedStorage ? selectedStorage.location : null,
      storage_address: selectedStorage ? selectedStorage.address : '',
      daily_customers: dailyCustomerCount,
      total_weight: productWeight,
    };

    try {
      const response = await fetch("http://127.0.0.1:5000/optimize", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const jsonData = await response.json();
      setOptimizationResult(jsonData);
    } catch (error) {
      console.error("Error optimizing routes:", error);
    }
  };

  // Map route data (example)
  const routeData = optimizationResult?.routes?.length
    ? optimizationResult.routes[0].route
    : [];

  // Determine map default center from selected storage or fallback
  const defaultCenter = storages.find(s => s.id === selectedStorageId)?.location || [0, 0];

  return (
    <div className="page-container">
      {/* Fullscreen Map as background */}
      <div className="map-fullscreen">
        <MapDisplay routeData={routeData} defaultCenter={defaultCenter} zoom={3} />
      </div>

      {/* Centered Card Container */}
      <div className="overlay-container">
        <div className="blue-card">
          <div className="blue-card-header">
            <h1>Delivery Optimizer</h1>
            <p>Your daily route optimization solution</p>
          </div>

          <div className="blue-card-content">
            <div className="input-group">
              <label>Daily Customer Count:</label>
              <input
                type="number"
                min="0"
                value={dailyCustomerCount}
                onChange={(e) => setDailyCustomerCount(Number(e.target.value))}
              />
            </div>

            <div className="input-group">
              <label>Select Storage:</label>
              <select
                value={selectedStorageId || ''}
                onChange={(e) => setSelectedStorageId(Number(e.target.value))}
              >
                {storages.map(storage => (
                  <option key={storage.id} value={storage.id}>
                    {storage.name} - {storage.address}
                  </option>
                ))}
              </select>
            </div>

            <div className="input-group">
              <label>Search Customers:</label>
              <input
                type="text"
                placeholder="Search customers..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>

            <div className="customer-list">
              {filteredCustomers.length === 0 ? (
                <p>No customers match your search criteria.</p>
              ) : (
                filteredCustomers.map((c) => (
                  <div
                    key={c.id}
                    className={`customer-item ${selectedCustomerIds.includes(c.id) ? 'selected' : ''}`}
                    onClick={() => handleCustomerToggle(c.id)}
                  >
                    <strong>{c.name}</strong>
                    <small>{c.address}</small>
                  </div>
                ))
              )}
            </div>

            <div className="input-group">
              <label>Trucks Needed:</label>
              <input
                type="number"
                min="0"
                value={numTrucks}
                onChange={(e) => setNumTrucks(Number(e.target.value))}
              />
            </div>

            <div className="input-group">
              <label>Product Weight (kg):</label>
              <input
                type="number"
                min="0"
                value={productWeight}
                onChange={(e) => setProductWeight(Number(e.target.value))}
              />
            </div>

            <button onClick={handleSubmit} className="submit-btn">
              Submit for Optimized Route
            </button>
          </div>
        </div>

        {/* Optionally display optimization results below the card */}
        {optimizationResult && (
          <div className="result-card">
            <h2>Optimization Result</h2>
            <pre>{JSON.stringify(optimizationResult, null, 2)}</pre>
          </div>
        )}
      </div>
    </div>
  );
}

export default DeliveryOptimizerSinglePage;
